/*
 * A389735  Standard composition numbers of integer compositions that do not
 *          comprise a finite arithmetic progression.
 * https://oeis.org/A389735
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th integer k such that the standard composition of
 *            k (A066099) is NOT an arithmetic progression. The sequence is
 *            generated by enumerating k≥1, computing the composition,
 *            checking if it fails to be an AP, and collecting those k’s in
 *            order
 * Range:     u8 n <= 209, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 81 terms through n = 9459 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/mem.h"

/* Helper:  return true iff the standard composition of k is NOT an AP */
static bool is_non_ap(idx_t k)
{
    /* positions of 1 bits in k, counted from LSB starting at 1 */
    int pos[64];
    int m = 0;
    idx_t x = k;
    int bit = 1;
    while (x) {
        if (x & 1U) pos[m++] = bit;
        x >>= 1U;
        ++bit;
        if (m >= 64) break;          /* safety, though k fits in 64 bits */
    }

    /* compositions of length < 3 are automatically AP */
    if (m <= 2) return false;

    /* first differences of positions (with prepend 0) */
    int diff[64];
    for (int i = 0; i < m; ++i) {
        if (i == 0) diff[i] = pos[0];
        else        diff[i] = pos[i] - pos[i-1];
    }

    /* reverse to get the composition parts */
    int comp[64];
    for (int i = 0; i < m; ++i) comp[i] = diff[m-1-i];

    /* check whether all consecutive differences are equal */
    for (int i = 0; i + 2 < m; ++i) {
        int d1 = comp[i+1] - comp[i];
        int d2 = comp[i+2] - comp[i+1];
        if (d1 != d2) return true;   /* not an AP */
    }
    return false;                    /* is an AP – exclude */
}

/* Cache of discovered terms */
static seq_t *cache = NULL;
static idx_t cache_len = 0;   /* number of cached terms */
static idx_t cache_cap = 0;   /* allocated capacity of cache array */
static idx_t last_k   = 0;    /* last integer k processed */

/* Required function */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined index – safe return */

    /* Ensure the cache has at least n terms */
    if (n > cache_len) {
        /* grow capacity if needed */
        if (cache_cap < n) {
            idx_t new_cap = cache_cap ? cache_cap << 1 : 64;
            if (new_cap < n) new_cap = n;
            seq_t *tmp = mem_resize(seq_t, cache, new_cap);
            cache = tmp;
            cache_cap = new_cap;
        }

        /* enumerate k's from where we left off */
        idx_t k = last_k + 1;
        while (cache_len < n) {
            if (is_non_ap(k)) {
                cache[cache_len++] = (seq_t)k;
            }
            ++k;
        }
        last_k = k - 1;
    }

    return cache[n - 1];
}
